/* @autogenerated */
import { inject, Signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { BreakpointObserver, Breakpoints } from '@angular/cdk/layout';
import { map } from 'rxjs';

/** Cuántas acciones de fila caben como icono según el ancho de pantalla; el resto va al menú "más". */
export function inlineIconCount(): Signal<number> {
  const observer = inject(BreakpointObserver);
  return toSignal(
    observer
      .observe([
        Breakpoints.XLarge, // >=1920
        Breakpoints.Large, // 1280–1919.98
        Breakpoints.Medium, // 960–1279.98
        Breakpoints.Small, // 600–959.98
        Breakpoints.XSmall, // <600
      ])
      .pipe(
        map(({ breakpoints: bp }) => {
          if (bp[Breakpoints.XLarge]) return 5;
          if (bp[Breakpoints.Large]) return 4;
          if (bp[Breakpoints.Medium]) return 3;
          return 0;
        }),
      ),
    { initialValue: 3 },
  );
}
